/** Other names of the networks' icons. */
const ALIASES: Record<string, string> = {
  mail: 'email',
  mobile: 'phone_2',
  trip_advisor: 'tripadvisor',
  x: 'twitter-x',
  'x-twitter': 'twitter-x',
};

/**
 * The icon of a name: the icon itself, an alias, the name without the
 * `-logo` suffix newer versions of the original theme give their icons, or
 * the name without its last parts (`instagram-alt` → `instagram`).
 */
export function socialIconName(name: string): string | undefined {
  let n = name.trim().toLowerCase();
  if (!n) return undefined;
  for (;;) {
    if (n in ICONS) return n;
    if (n in ALIASES) return ALIASES[n];
    const shorter = n.endsWith('-logo') ? n.slice(0, -5) : n.replace(/[-_][^-_]*$/, '');
    if (shorter === n || !shorter) return undefined;
    n = shorter;
  }
}

/**
 * The SVG of an icon: by its name, else by the network of the element
 * (its id, `facebook-2` for a second one), else a generic link.
 */
export function socialIcon(name: string, network = ''): string {
  const key = socialIconName(name) ?? socialIconName(network) ?? 'rss';
  const [viewBox, paths] = ICONS[key]!;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" width="18" height="18" fill="currentColor">${paths}</svg>`;
}
